import{_ as i,H as t,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"19 | 视频录制项目实战：场景分析与架构设计","description":"","frontmatter":{},"headers":[{"level":2,"title":"视频录制器的场景分析","slug":"视频录制器的场景分析","link":"#视频录制器的场景分析","children":[]},{"level":2,"title":"音频模块架构设计","slug":"音频模块架构设计","link":"#音频模块架构设计","children":[{"level":3,"title":"Android 平台的实现","slug":"android-平台的实现","link":"#android-平台的实现","children":[]},{"level":3,"title":"Input 模块","slug":"input-模块","link":"#input-模块","children":[]},{"level":3,"title":"Output 模块","slug":"output-模块","link":"#output-模块","children":[]},{"level":3,"title":"PCM 队列","slug":"pcm-队列","link":"#pcm-队列","children":[]},{"level":3,"title":"Consumer 模块","slug":"consumer-模块","link":"#consumer-模块","children":[]},{"level":3,"title":"iOS 平台的实现","slug":"ios-平台的实现","link":"#ios-平台的实现","children":[]},{"level":3,"title":"Input 模块","slug":"input-模块-1","link":"#input-模块-1","children":[]},{"level":3,"title":"Output 模块","slug":"output-模块-1","link":"#output-模块-1","children":[]},{"level":3,"title":"PCM 队列","slug":"pcm-队列-1","link":"#pcm-队列-1","children":[]},{"level":3,"title":"Consumer 模块","slug":"consumer-模块-1","link":"#consumer-模块-1","children":[]}]},{"level":2,"title":"视频模块架构设计","slug":"视频模块架构设计","link":"#视频模块架构设计","children":[{"level":3,"title":"Android 平台的实现","slug":"android-平台的实现-1","link":"#android-平台的实现-1","children":[]},{"level":3,"title":"iOS 平台的实现","slug":"ios-平台的实现-1","link":"#ios-平台的实现-1","children":[]}]},{"level":2,"title":"风险分析","slug":"风险分析","link":"#风险分析","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"快手·移动端音视频开发实战/19｜视频录制项目实战：场景分析与架构设计.md","filePath":"快手·移动端音视频开发实战/19｜视频录制项目实战：场景分析与架构设计.md","lastUpdated":1795563308000}'),n={name:"快手·移动端音视频开发实战/19｜视频录制项目实战：场景分析与架构设计.md"};function r(o,e,p,u,s,d){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_19-视频录制项目实战-场景分析与架构设计" tabindex="-1">19 | 视频录制项目实战：场景分析与架构设计 <a class="header-anchor" href="#_19-视频录制项目实战-场景分析与架构设计" aria-label="Permalink to &quot;19 | 视频录制项目实战：场景分析与架构设计&quot;">​</a></h1><p>你好，我是展晓凯。今天我们来一起学习视频录制器的场景设计与架构分析。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/19/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/19/1.png" alt=""></a></p><p>前面我们用了 9 节课学习了音视频采集和编码方面的知识。现在是时候用一个视频录制器项目把这些知识点串联起来了。这个项目运行起来后，我们就可以采集音频和视频，最终保存成一个视频文件了。这个视频录制器是录播场景下非常重要的一个模块，之后你也可以以这个项目为基础，做一些扩展和改动（码率自适应、网络抖动处理、关键帧间隔设置等），改造成一个直播场景的视频推流器。</p><p>整个视频录制器项目，我会分为三部分来讲解，每一部分会解决一个核心问题。</p><ul><li><p>第一部分：从场景分析入手，设计视频录制器项目的架构，让你明白视频录制器的顶层设计和模块拆分，并了解其中的关键点。</p></li><li><p>第二部分：基于架构设计，实现录制器中的底层核心模块，包括音频的采集和编码，视频的采集和编码，把前面第 10 节课到第 18 节课的知识点，套用到整个项目里。</p></li><li><p>第三部分：讲解 Mux 模块和中控系统，让整个录制器项目跑起来，最终分析一下整体录制器的扩展性，让你完全掌握视频录制的精髓。</p></li></ul><p>接下来我们就一起来看一下视频录制器的场景分析和架构设计部分吧。</p><h2 id="视频录制器的场景分析" tabindex="-1">视频录制器的场景分析 <a class="header-anchor" href="#视频录制器的场景分析" aria-label="Permalink to &quot;视频录制器的场景分析&quot;">​</a></h2><p>我们在工作中完成一个项目或者产品的迭代时，首先要做的就是场景分析，场景分析不是要写一堆别人看不懂甚至看都不看的文档，而是站在技术角度思考这个场景的输入、输出和存在的技术风险点，目的是辅助我们设计出一个好的架构来实现这个项目。</p><p>视频录制器运行起来之后，需要展示给用户一个视频预览页面，让用户可以看到摄像头里采集到的画面，用户将预览画面调整满意之后，就可以点击录制按钮。接下来录制器需要把用户的声音和画面全都录制下来，并编码生成一个 MP4 文件。在录制过程中，也可以让用户选择是否需要开启背景音乐，方便用户唱歌或展示舞蹈等。</p><p>场景看上去还是挺简单的，但是针对这个场景如何设计出一个合理的架构却是一个比较复杂的工作。从录制视频的角度来讲，每个平台都有自己独特的 API 可供开发者调用，但是要想合理地使用这些 API，还需要通过架构的手段拆分出具体的模块，定义清楚每个模块的边界或者职责，再根据平台特性为某个技术模块确定实现细节。基于业务场景分析，录制器项目可拆分成两部分，一部分是音频，另一部分是画面（视频）。</p><h2 id="音频模块架构设计" tabindex="-1">音频模块架构设计 <a class="header-anchor" href="#音频模块架构设计" aria-label="Permalink to &quot;音频模块架构设计&quot;">​</a></h2><p>我们先来看音频模块的架构设计示意图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/19/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/19/2.png" alt=""></a></p><p>乍一看，你可能会觉得这个架构比较复杂，因为图里包含了两个平台的音频架构，同时链路里还包括了 BGM 的播放。不过，你别着急，我会带你来逐一分析。</p><p>我们先从最顶层来解读这张架构图，图最上边的一部分从左到右依次为 Input、Output、PCM队列和 Consumer，下面来逐一看一下这 4 个模块。</p><ul><li><p>Input 代表输入模块，输入之一是麦克风，用来采集用户的声音；第二个是伴奏文件的解码器，用来解码用户选择的背景音乐，所以输入模块要由这两部分共同来实现。</p></li><li><p>Output 代表输出模块，输出之一就是利用渲染音频的 API 把背景音乐的声音播放出来，在iOS 平台，如果用户戴着有线耳机的话，可以把用户自己发出的声音同时播放出来，来达到</p></li><li><p>耳返监听的功能；第二个是记录数据，把背景音乐和用户声音的数据保存下来；那保存到哪里呢？就是接下来介绍的数据存储模块。</p></li><li><p>PCM 队列代表数据存储模块，把背景音乐和用户声音的 PCM 数据存入队列里，这个队列应该保证多线程访问时线程的安全性。</p></li><li><p>Consumer 代表消费者模块，负责从数据存储模块里取出 PCM 数据，做音频 AAC 的编码，最终封装到 MP4 文件里。从数据存储模块角度来看，它属于一个消费者的角色，所以我们也叫它消费者模块。</p></li></ul><p>拆分完模块之后，接下来就是在 Andorid 和 iOS 平台确定技术选型来完成模块的职责。</p><h3 id="android-平台的实现" tabindex="-1">Android 平台的实现 <a class="header-anchor" href="#android-平台的实现" aria-label="Permalink to &quot;Android 平台的实现&quot;">​</a></h3><p>架构图的第二行是 Android 平台的实现。注意，核心系统还是在 Native 层构建的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/19/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/19/3.png" alt=""></a></p><h3 id="input-模块" tabindex="-1">Input 模块 <a class="header-anchor" href="#input-模块" aria-label="Permalink to &quot;Input 模块&quot;">​</a></h3><p>输入模块主要分为两部分，一部分是采集人声，一部分是解码 BGM。</p><ul><li><p>采集人声时，使用 AudioRecord 这个 API 是兼容性最好的。如果想要更低延时的能力就再配备上 Oboe，然后根据黑白名单和用户的设置在这两种使用方法中切换。采集到人声之后，要放到数据存储模块里。</p></li><li><p>解码伴奏，我们可以基于 FFmpeg 写一个伴奏的解码调度器，把背景音乐文件解码成 PCM数据，并放入 PCM 队列（解码调度器内部维护的队列）里，以供 Output 模块从队列里取出 PCM 数据播放给用户听。</p></li></ul><h3 id="output-模块" tabindex="-1">Output 模块 <a class="header-anchor" href="#output-模块" aria-label="Permalink to &quot;Output 模块&quot;">​</a></h3><p>输出模块也分为两部分，一部分是人声的耳返，另一部分是伴奏 BGM 的播放。</p><ul><li><p>人声耳返，Android 设备上的耳返监听方案还不是特别成熟，目前业界最佳实践分为两种，一种是使用厂商的硬件耳返，这个时候必须要使用 Java 层的 AudioRecord 来采集音频。另外一种是自己实现的软件耳返，使用 Oboe 来实现。其实除了 K 歌 App 之外，实时耳返的需求没有这么大，你可以根据自己的场景来规划这部分的精力投入。</p></li><li><p>伴奏播放，要让用户听得到背景音乐，我们使用 AudioTrack 来播放 Input 模块解码好的伴奏 PCM 数据，同时把播放的伴奏放到数据存储模块里。</p></li></ul><h3 id="pcm-队列" tabindex="-1">PCM 队列 <a class="header-anchor" href="#pcm-队列" aria-label="Permalink to &quot;PCM 队列&quot;">​</a></h3><p>因为核心系统都是构建在 Native 层的，所以我们使用 C++ 自己书写一个线程安全的链表，来实现队列功能，提供对应的 Put、Get、Abort、Size 等接口供生产者和消费者使用，为了方便消费者获取数据，可以把这个队列改造成一个 Blocking Queue 的形式。</p><h3 id="consumer-模块" tabindex="-1">Consumer 模块 <a class="header-anchor" href="#consumer-模块" aria-label="Permalink to &quot;Consumer 模块&quot;">​</a></h3><p>消费者模块需要单独开启一个线程，来从数据存储模块里获取伴奏的 PCM 数据和人声的PCM 数据。这里可以对 PCM 数据做一些处理，比如给人声增加音效、AEC、人声伴奏对齐调整。然后把两个 PCM 的 Buffer 合并成一轨音频数据，接着用 MediaCodec 或者libfdk_aac 把 PCM 数据编码成 AAC 的码流，最终利用 FFmpeg 的 Muxer 模块把编码后的AAC 数据封装到 MP4 文件的声音轨道里。</p><p>这样 Andorid 平台的技术选型就说完了，你可以对照架构图里 Android 部分再梳理一遍。接下来，我们看 iOS 平台的实现。</p><h3 id="ios-平台的实现" tabindex="-1">iOS 平台的实现 <a class="header-anchor" href="#ios-平台的实现" aria-label="Permalink to &quot;iOS 平台的实现&quot;">​</a></h3><p>架构图的第三行是 iOS 平台的实现，相比 Android 平台，iOS 会简单一些。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/19/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/19/4.png" alt=""></a></p><h3 id="input-模块-1" tabindex="-1">Input 模块 <a class="header-anchor" href="#input-模块-1" aria-label="Permalink to &quot;Input 模块&quot;">​</a></h3><p>输入模块主要分为两部分，一部分是采集人声，另一部分是解码 BGM。</p><ul><li><p>采集人声应该使用 RemoteIO 这个 AudioUnit，启用它的 InputElement 采集人声数据。采集到人声之后，如果要做处理直接在 AUGraph 里加入音效的 AudioUnit 节点，最终汇入MixerAudioUnit 里。</p></li><li><p>解码伴奏，在 AUGraph 里直接使用 AudioFilePlayer 这个 AudioUnit 解码伴奏，如果要加入升降调的处理，可以在这个节点之后连接上一个 NewTimepitch 的 AudioUnit。</p></li></ul><p>然后使用一个 Mixer 的 AudioUnit 把人声和伴奏两轨声音合并起来，输出给下面的 Output 模块。</p><h3 id="output-模块-1" tabindex="-1">Output 模块 <a class="header-anchor" href="#output-模块-1" aria-label="Permalink to &quot;Output 模块&quot;">​</a></h3><p>如果想要完成伴奏和耳返播放功能，这里使用 RemoteIO 这个 AudioUnit 的 OutputElement，把 MixerUnit 输出的音频播放出来就可以了。接下来还需要实现把 PCM 数据放入 PCM 队列的功能，这就需要给 AudioUnit 注册一个回调函数，利用 Converter 的 AudioUnit 把转换成SInt16 采样格式表示的 PCM 数据放到音频队列里。</p><h3 id="pcm-队列-1" tabindex="-1">PCM 队列 <a class="header-anchor" href="#pcm-队列-1" aria-label="Permalink to &quot;PCM 队列&quot;">​</a></h3><p>我们可以使用 C++ 自己写一个线程安全的链表，提供先入先出的接口来完成队列的功能，这个队列的代码可以和 Andorid 平台共享一份代码。</p><h3 id="consumer-模块-1" tabindex="-1">Consumer 模块 <a class="header-anchor" href="#consumer-模块-1" aria-label="Permalink to &quot;Consumer 模块&quot;">​</a></h3><p>最后是 Consumer 模块的实现，开启一个线程在后台将 PCM 队列中的数据取出来之后，使用AudioToolbox 或者 libfdk_aac 编码成 AAC 码流。最后利用 FFmpeg 把编码后的 AAC 数据封装到 MP4 文件的声音轨道里。这个模块主要是使用 C++ 语言调用 FFmpeg 的 API 来实现的，所以可以和 Android 平台共享一份代码，你可以对照架构图的 iOS 部分再梳理一下。</p><p>音频架构分析得差不多了，下面我们看一下视频部分的架构。</p><h2 id="视频模块架构设计" tabindex="-1">视频模块架构设计 <a class="header-anchor" href="#视频模块架构设计" aria-label="Permalink to &quot;视频模块架构设计&quot;">​</a></h2><p>相比于音频的架构设计，视频的架构相对简单一些，整体架构图如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/19/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BF%AB%E6%89%8B%C2%B7%E7%A7%BB%E5%8A%A8%E7%AB%AF%E9%9F%B3%E8%A7%86%E9%A2%91%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/19/5.png" alt=""></a></p><p>可以看到架构图的第一行，和音频架构图类似，分为输入、输出、队列和消费者四个模块，每个模块完成的功能这里就不再重复了，接下来我们直接确定一下各个模块在两个平台的技术选型。</p><h3 id="android-平台的实现-1" tabindex="-1">Android 平台的实现 <a class="header-anchor" href="#android-平台的实现-1" aria-label="Permalink to &quot;Android 平台的实现&quot;">​</a></h3><p>Input 模块的实现，直接使用 Android 系统为我们提供的 Camera 来采集，需要注意的是，要以纹理回调的方式使用它。Output 模块分为两部分，一部分是预览，通过使用 OpenGL ES结合 Java 层的 Surface(Texture)View 来实现；另外一部分是编码，建议你优先使用硬件 ****编码器给视频编码。如果有兼容问题，使用 libx264 软件编码作为保底的方案来实现，最终编码成 H264 的数据。（可参考第 16 课和第 17 课的内容）</p><p>这里和第 17 课的不同之处是编码之后的 H264 数据不要直接写入文件，而是要放到第三个模块——H264 的队列里。对于 H264 的队列，我们同样可以使用一个线程安全的链表来实现，链表里每一个节点元素都是一帧 H264 的数据，也就是一个 Annex-B 格式的 NALU。</p><p>最后一个模块是消费者模块，我们在 Consumer 这个模块取出队列里的 H264 数据包，然后利用 FFmpeg 的 Mux 模块封装到 MP4 的视频轨道里，这就和之前封装到这个文件里的音频轨道组成了一个完整的 MP4 文件，也就是我们最终输出的 MP4 文件。</p><h3 id="ios-平台的实现-1" tabindex="-1">iOS 平台的实现 <a class="header-anchor" href="#ios-平台的实现-1" aria-label="Permalink to &quot;iOS 平台的实现&quot;">​</a></h3><p>在 iOS 平台上，Input 模块的实现自然会使用系统提供给开发者的 Camera 这个 API 来实现。Output 模块，分为预览和编码，预览的实现直接使用 EAGL 和 OpenGL 再结合自定义的一个UIView 来完成；编码的实现是使用 VideoToolbox 进行硬件编码，直接使用我们的 ELImage框架来完成即可。我们第 14 节课和第 18 节课重点讲解过，这里的不同之处在于编码之后的 H264 数据不要写入文件里，而是应该放到 H264 的队列里。</p><p>第三个模块是 H264 队列模块，可以使用一个线程安全的链表来实现，链表里每一个节点元素都是 H264 的数据包，这个模块的实现可以和 Android 平台共享一份代码。</p><p>最后一个模块就是消费者模块，在 Consumer 模块取出队列里的 H264 数据包，然后利用FFmpeg 的 Mux 模块把 H264 的包封装到 MP4 的视频轨道部分，和之前封装到这个文件中的音频轨道共同组成一个完整的 MP4 文件。这个模块主要使用 C++ 语言调用 FFmpeg 的 API来实现，也可以和 Android 平台共享一份代码。</p><p>以上就是我们视频录制器整体架构的设计和实现，但好的架构设计还需要给出具体的风险评估，接下来我们一起看一下。</p><h2 id="风险分析" tabindex="-1">风险分析 <a class="header-anchor" href="#风险分析" aria-label="Permalink to &quot;风险分析&quot;">​</a></h2><p>整个架构的风险点有两个：</p><ul><li><p>编码器方面，各平台（尤其是 Android 平台）硬件编码器的兼容性问题，还有如果在Android 平台使用软件编码器的话，中低端机上软件编码器的性能问题。</p></li><li><p>音视频对齐方面，由于音视频是分开采集的，这里我们需要考虑音视频同步的问题。</p></li></ul><p>最后再补充一点测试用例方面的注意事项，在测试完 App 的 Top 机型和主流系统之后，要重点测试 Android 平台的硬件编码覆盖面，还要测试音视频对齐的问题，这里我们可以使用自动化检测音画对齐的工具来处理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>最后，我们可以一起来回顾一下。这节课我们从视频录制器的场景分析入手，设计出了一个视频录制器的架构。</p><p>音频的输入包括采集音频和解码伴奏，输出包含播放音频、把 PCM 数据存入队列里，消费者模块会从队列里取出 PCM 数据进行编码，最后合并到文件里。</p><p>视频架构会更简单一些，输入模块就是摄像头采集图像，输出模块包含两部分，一部分是让用户预览到图像，另外一部分是编码成 H264 的码流放到队列里，消费者模块从队列里获取数据并合并到最终的 MP4 文件里。</p><p>无论是音频部分还是视频部分，我们底层的设计都是 Input、Output、队列和消费者模块，在音视频的架构设计中基本都包含这几个模块。其中 Input、Output 模块和平台的相关性是比较大的，而队列和消费者模块在两个平台的实现其实是一模一样的，所以我们可以把这部分代码抽象成统一的接口，使用 C++ 来书写，跨平台同时运行在 Android 与 iOS 上，这样可以提升开发效率，降低维护成本。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>我来考考你，如果让你基于这个架构设计一个推流器的架构，你思考一下要在此基础上加入哪些模块，这些模块的职责又是什么？欢迎把你的答案留在评论区，也欢迎你把这节课分享给更多对音视频感兴趣的朋友，我们一起交流、共同进步。下节课再见！</p>',70)])])}const E=i(n,[["render",r]]);export{A as __pageData,E as default};
